package com.circlenet.domain.trust;
import java.security.Principal;import java.util.*;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/trust") public class TrustController{private final TrustService service;public TrustController(TrustService s){service=s;}public record AddPerson(Long userId,String kind){}public record EmergencyStart(Long ownerUserId,String reason){}public record Decision(boolean approved){}
 @GetMapping("/people") public List<TrustService.Person> people(Principal p,@RequestParam String kind){return service.mine(id(p),kind);}@GetMapping("/people/inbound") public List<TrustService.Person> inbound(Principal p,@RequestParam String kind){return service.inbound(id(p),kind);}@PostMapping("/people") public TrustService.Person add(Principal p,@RequestBody AddPerson r){return service.add(id(p),r.userId(),r.kind());}@DeleteMapping("/people/{userId}") public ResponseEntity<Void> remove(Principal p,@PathVariable Long userId,@RequestParam String kind){service.remove(id(p),userId,kind);return ResponseEntity.noContent().build();}
 @GetMapping("/role-models") public List<TrustService.Person> roleModels(Principal p){return service.roleModels(id(p));}@PostMapping("/role-models/{userId}/follow") public TrustService.Person follow(Principal p,@PathVariable Long userId){return service.follow(id(p),userId);}@DeleteMapping("/role-models/{userId}/follow") public ResponseEntity<Void> unfollow(Principal p,@PathVariable Long userId){service.unfollow(id(p),userId);return ResponseEntity.noContent().build();}
 @GetMapping("/emergencies") public List<TrustService.EmergencyRequest> emergencies(Principal p){return service.emergencyRequests(id(p));}@PostMapping("/emergencies") public TrustService.EmergencyRequest emergency(Principal p,@RequestBody EmergencyStart r){return service.request(id(p),r.ownerUserId(),r.reason());}@PostMapping("/emergencies/{requestId}/decision") public TrustService.EmergencyRequest decide(Principal p,@PathVariable Long requestId,@RequestBody Decision r){return service.decide(id(p),requestId,r.approved());}@GetMapping("/emergencies/{requestId}/documents") public List<TrustService.EmergencyDocument> documents(Principal p,@PathVariable Long requestId){return service.documents(id(p),requestId);}@GetMapping("/emergencies/{requestId}/documents/{postId}/media") public ResponseEntity<Resource> media(Principal p,@PathVariable Long requestId,@PathVariable Long postId){var a=service.document(id(p),requestId,postId);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+(a.name()==null?"document":a.name().replace("\"",""))+"\"").contentType(MediaType.parseMediaType(a.type())).body(a.resource());}private Long id(Principal p){return Long.valueOf(p.getName());}}
